@canInWorkspace('inbox.edit')
<details class="card-premium p-5 mb-5" x-data="formAiStudio({fields:()=>fields,estimate:@js(route('user.forms.ai.estimate',$form)),generate:@js(route('user.forms.ai.generate',$form))})">
<summary class="font-bold cursor-pointer flex gap-3 items-center"><i class="fas fa-wand-magic-sparkles text-blue-500"></i>Create or edit with AI <span class="text-xs font-normal" style="color:var(--text-muted)">Prompt · image · PDF · estimate first</span></summary>
<div class="space-y-3 mt-4">
<p class="text-xs" style="color:var(--text-muted)">Describe the industry, audience and purpose, paste questions, or attach a printed or handwritten form (PDF: up to 6 pages; images or PDF: up to 10 MB). AI can propose up to 40 new or changed fields per draft. Edits preserve untouched questions; you review them before applying. Your supplied text and file are sent to the configured AI provider after you request generation.</p>
<label class="block text-sm">Action<select x-model="mode" @change="quote=null" class="theme-input block"><option value="edit">Edit existing questions</option><option value="create">Create a new set of questions</option></select></label>
<textarea x-model="instruction" @input="quote=null" class="theme-input w-full" rows="3" maxlength="6000" placeholder="Create a volunteer registration form for a local community: availability, skills, consent…"></textarea>
<label class="block text-sm">Optional source<input class="theme-input block" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" @change="file=$event.target.files[0]||null;quote=null"><span class="text-xs">JPEG, PNG, WebP or PDF · 10 MB · up to 6 PDF pages. Review uncertain handwriting carefully.</span></label>
<div class="flex flex-wrap gap-3 items-center"><button type="button" @click="estimate()" :disabled="busy||!instruction.trim()" class="btn-ghost">Estimate coins</button><template x-if="quote"><span class="text-sm" x-text="'Estimated up to '+quote.estimated_coins+' coins · balance '+quote.balance+' · valid 10 minutes'"></span></template><button type="button" @click="generate()" :disabled="busy||!quote||quote.balance<quote.estimated_coins" class="btn-primary">Generate draft</button><span x-show="busy" class="text-sm">Processing…</span></div>
<p role="alert" x-show="message" x-text="message" class="text-sm text-red-500"></p>
<template x-if="draft"><div class="card-premium p-4 space-y-3"><h3 class="font-bold" x-text="draft.title"></h3><p class="text-sm" x-text="draft.description"></p><p class="text-xs" x-text="draft.coins_spent+' coins used'"></p><template x-for="(warning,i) in draft.warnings" :key="i"><p class="text-sm text-amber-600" x-text="warning"></p></template><ol class="space-y-2 max-h-80 overflow-auto"><template x-for="f in draft.fields" :key="f.id"><li class="text-sm"><strong x-text="f.label||f.type"></strong><span class="text-xs ml-2" x-text="f.type+(f.required?' · required':'')"></span><p x-show="f.help" x-text="f.help"></p><p x-show="f.options" x-text="(f.options||[]).join(' · ')"></p></li></template></ol><button type="button" class="btn-primary" @click="apply()">Apply reviewed draft to editor</button><button type="button" class="btn-ghost" @click="draft=null">Discard draft</button></div></template>
</div></details>
@endcanInWorkspace
